import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.BKVF-9lJ.js";const g=JSON.parse('{"title":"mfe-forge dev","description":"","frontmatter":{},"headers":[],"relativePath":"cli/dev.md","filePath":"cli/dev.md","lastUpdated":1791840224000}'),d={name:"cli/dev.md"};function i(r,e,c,n,l,p){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="mfe-forge-dev" tabindex="-1"><code>mfe-forge dev</code> <a class="header-anchor" href="#mfe-forge-dev" aria-label="Permalink to &quot;\`mfe-forge dev\`&quot;">​</a></h1><p>Start development servers for discovered apps and hosts.</p><h2 id="synopsis" tabindex="-1">Synopsis <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;Synopsis&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mfe-forge dev [options]</span></span></code></pre></div><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>dev</code> selects target apps, then runs the root <code>package.json</code> script <code>dev:&lt;scope&gt;:&lt;name&gt;</code> for each one. Those scripts are written by <a href="./generate#root-package-json-script"><code>generate</code></a> and delegate to the app&#39;s own <code>dev</code> script through the package manager&#39;s workspace filter.</p><ul><li><strong>One target:</strong> <code>&lt;pm&gt; run dev:&lt;scope&gt;:&lt;name&gt;</code> runs in the foreground with inherited stdio.</li><li><strong>Several targets:</strong> the commands run in parallel through <code>npx --yes concurrently --kill-others-on-fail</code>, with output prefixed by app name.</li></ul><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>-s</code>, <code>--scope &lt;scope&gt;</code></td><td>string</td><td></td><td>Run every app in the scope, plus <code>&lt;scope&gt;/host</code> if it exists.</td></tr><tr><td><code>-a</code>, <code>--app &lt;app&gt;</code></td><td><code>scope/name</code> or bare name</td><td></td><td>Run one app. A bare name must be unambiguous across scopes.</td></tr><tr><td><code>-p</code>, <code>--parallel &lt;n&gt;</code></td><td>number</td><td><code>10</code></td><td>Accepted but <strong>not applied</strong>; all selected targets start at once.</td></tr><tr><td><code>--host-only</code></td><td>boolean</td><td><code>false</code></td><td>Run only hosts (<code>apps/&lt;scope&gt;/host</code>).</td></tr><tr><td><code>--build-watch</code></td><td>boolean</td><td><code>false</code></td><td>Accepted but <strong>not implemented</strong>; it has no effect.</td></tr><tr><td><code>-h</code>, <code>--help</code></td><td>boolean</td><td></td><td>Show help.</td></tr></tbody></table><p>Precedence when several selectors are given: <code>--app</code>, then <code>--scope</code>, then <code>--host-only</code>. With none, every discovered app (hosts included) is started.</p><div class="info custom-block"><p class="custom-block-title">Configuration fields not used</p><p><code>dev.parallelLimit</code> and <code>dev.autoStartHost</code> are validated but not read by <code>dev</code>.</p></div><h2 id="target-discovery" tabindex="-1">Target discovery <a class="header-anchor" href="#target-discovery" aria-label="Permalink to &quot;Target discovery&quot;">​</a></h2><p>An app is any directory <code>apps/&lt;scope&gt;/&lt;name&gt;/</code> that contains <code>vite.config.ts</code>. A host is the app named <code>host</code> in a scope. Design systems and <code>packages/*</code> are not started.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mfe-forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # everything</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mfe-forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --scope</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # shop/* plus shop/host</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mfe-forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cart</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # only shop/cart (if &quot;cart&quot; is unique)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mfe-forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host-only</span></span></code></pre></div><h2 id="behavior-details" tabindex="-1">Behavior details <a class="header-anchor" href="#behavior-details" aria-label="Permalink to &quot;Behavior details&quot;">​</a></h2><ul><li><code>concurrently</code> is fetched on demand with <code>npx --yes</code>, so the first multi-app run needs network access, and npm must be available even in Bun or pnpm projects.</li><li><code>--kill-others-on-fail</code> stops every server as soon as one exits with an error.</li><li>If the <code>concurrently</code> process itself fails (including when a server crashes), the CLI <strong>falls back to starting each target sequentially</strong> in the foreground. Each sequential server blocks until it exits; an exit prints <code>⚠ &lt;app&gt; exited</code> and moves on to the next target.</li><li>The script name for <code>shop/cart</code> is <code>dev:shop:cart</code>. If you remove that root script, <code>dev</code> cannot start the app.</li></ul><div class="warning custom-block"><p class="custom-block-title">Workspace globs</p><p>The default scripts use <code>&lt;pm&gt; --filter &lt;package&gt;</code>, which only finds apps that are workspace members. The <code>init</code> template&#39;s <code>apps/*</code> glob does not match <code>apps/&lt;scope&gt;/&lt;name&gt;</code>; use <code>apps/*/*</code>. pnpm also needs a <code>pnpm-workspace.yaml</code>. See <a href="./init#files-produced"><code>init</code></a>.</p></div><h2 id="failure-modes" tabindex="-1">Failure modes <a class="header-anchor" href="#failure-modes" aria-label="Permalink to &quot;Failure modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Result</th></tr></thead><tbody><tr><td><code>--app</code> does not resolve</td><td><code>App &quot;&lt;app&gt;&quot; not found</code>, exit <code>1</code>.</td></tr><tr><td>No targets matched (empty project, empty scope, no hosts)</td><td><code>No apps found to run</code>, exit <code>0</code>.</td></tr><tr><td>The single target&#39;s script fails</td><td><code>Dev server failed</code>, exit <code>2</code>.</td></tr><tr><td>Configuration invalid</td><td>Exit <code>3</code>.</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./generate"><code>generate</code></a> — creates the <code>dev:*</code> scripts</li><li><a href="./doctor"><code>doctor</code></a> — checks port conflicts and workspaces</li><li><a href="./../troubleshooting">Troubleshooting</a></li></ul>`,22)])])}const u=t(d,[["render",i]]);export{g as __pageData,u as default};
